import type { BrowserContext } from 'playwright-core';
import { readFileSync } from 'node:fs';
export function douyinFixture(video:string){
 const controls={submissions:0,navigations:0,hold:false,release:()=>{},waiting:false,unknown:false,loggedIn:true,holdSubmit:false,submitWaiting:false,submitRelease:()=>{}};let context:BrowserContext|undefined;
 const attach=async(c:BrowserContext)=>{context=c;await c.exposeBinding('bffBeforeSubmit',async()=>{if(controls.holdSubmit){controls.submitWaiting=true;await new Promise<void>(r=>{controls.submitRelease=r;});controls.submitWaiting=false;}});await c.addCookies([{name:'uid_tt',value:'12345',domain:'.douyin.com',path:'/'},{name:'sessionid',value:'fixture-cookie',domain:'.douyin.com',path:'/'}]);await c.route('**/*',async route=>{const u=new URL(route.request().url());if(u.pathname==='/clip.webm'){await route.fulfill({contentType:'video/webm',body:readFileSync(video)});return;}if(u.pathname.includes('/digg/')){controls.submissions++;await route.fulfill({contentType:'application/json',body:JSON.stringify({status_code:0})});return;}
  if(u.pathname.includes('/video/')){controls.navigations++;if(controls.hold){controls.waiting=true;await new Promise<void>(r=>{controls.release=r;});controls.waiting=false;}}
  const id=/\/video\/(\d+)/.exec(u.pathname)?.[1]??'1234567890123456788';await route.fulfill({contentType:'text/html',body:`<!DOCTYPE html><html><head><meta charset="utf-8"><title>夹具海洋 - 抖音</title></head><body>${controls.loggedIn?'<img data-e2e="user-avatar" alt="夹具账号" width="20" height="20">':'<p>扫码登录</p>'}<section data-e2e="video-detail" class="video_${id}"><h1 data-e2e="video-title">夹具海洋</h1><a href="/user/fixture">@夹具作者</a><video autoplay muted loop width="640" height="360" src="/clip.webm"></video><button data-e2e="video-player-digg" data-e2e-state="no-digged" onclick="(async()=>{await window.bffBeforeSubmit();fetch('/aweme/v1/web/commit/item/digg/',{method:'POST',body:'aweme_id=${id}&type=1'}).then(()=>{${controls.unknown?'':'this.setAttribute(\'data-e2e-state\',\'digged\')'}})})()">点赞</button></section><a href="/video/${id}">夹具海洋</a></body></html>`});});};
 return {controls,attach,account:async(id:string)=>context!.addCookies([{name:'uid_tt',value:id,domain:'.douyin.com',path:'/'}])};
}
